 jsonb_build_array('عدم تصمیم‌گیری صرف بر مبنای فرض بدون مراجعه به WPS تعمیر مصوب', 'بررسی الزامات کد طراحی درباره نیاز PWHT برای ترمیم فولادهای حساس', 'مشورت با مهندس متالورژی برای تصمیم نهایی', 'مستندسازی کامل تصمیم و مبنای فنی آن'),
