 jsonb_build_array('تعمیر جوش بدون بررسی نیاز به PWHT مجدد', 'فرض این‌که چون جوش اصلی PWHT شده، تعمیر نیازی به آن ندارد'),
 'ASME Section IX / AWS D1.1 (الزامات PWHT برای تعمیر جوش)'),

('welding_supervisor','GENERAL','مدیریت زنجیره صلاحیت جوشکاران در پروژه چندفازی','L2',
